mapper.select:
SELECT TO_CHAR(F.FREE_NO) AS FREE_NO, F.EMPID, F.LOCAL_NAME, F.FLAG
  FROM EDU_FREE_EMPLOYEE F
 WHERE F.BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND F.ACTIVITY = '1'
   AND F.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
 ORDER BY F.FREE_NO

mapper.delete:
DELETE FROM EDU_FREE_EMPLOYEE
 WHERE BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND ACTIVITY = '1'
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND EMPID = #{empId, jdbcType=VARCHAR}

DELETE FROM EDU_STUDENT_CHECK
 WHERE BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND ACTIVITY = '1'
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND STU_EMPID = #{empId, jdbcType=VARCHAR}

mapper.select:
SELECT S.FINAL_STUDENT_EMPID AS EMPID, S.FINAL_STUDENT_NAME AS NAME
  FROM EDU_FINAL_STUDENT S
 WHERE S.BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND S.ACTIVITY = '1'
   AND S.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
 ORDER BY S.FINAL_NO

mapper.delete:
DELETE FROM EDU_FINAL_STUDENT
 WHERE BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND ACTIVITY = '1'
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

mapper.select:
SELECT T.TEA_EMPID || '|' || T.STU_EMPID FROM EDU_TEACHER_CHECK T
 WHERE T.BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM EDU_TEACHER_CHECK
 WHERE BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND TEA_EMPID = #{teaEmpId, jdbcType=VARCHAR}
   AND STU_EMPID = #{stuEmpId, jdbcType=VARCHAR}
